mapper.select:
SELECT pda.STATENO, pda.DISCARD_STATUS,
std.RECEIVED_DATE, std.EHARS_IMPORT_DATE, std.DOCUMENT_ID, std.CURRENT_PROCESS_STATUS, std.BIRTH_SEX, std.VITAL_STATUS, std.XLAB, std.PHYS_HIV, std.RACE_ASIAN, std.RACE_BLACK, std.RACE_INDIAN, std.RACE_OTHER, std.RACE_PACIFIC, std.RACE_UNKNOWN, std.RACE_WHITE, std.EHARS_STATUS_CD, std.DOB_TEXT, std.DOD_TEXT, std.HIV_DX_DATE_TEXT, std.AIDS_DX_DATE_TEXT, std.HIV_AIDS_DX_DATE_TEXT, std.CUR_ADDRESS_DATE_TEXT, std.SAMPLE_DATE_HIV1_TEXT, std.SAMPLE_DATE_HIV2_TEXT, std.SAMPLE_DATE_HIV3_TEXT, std.XLAB_DATE_TEXT, std.PHYS_HIV_DATE_TEXT, std.SAMPLE_DATE_AIDS_TEXT, std.OI_DX_DATE_TEXT, std.VL_RECENT_DATE_TEXT, std.CD4_RECENT_CNT_DATE_TEXT, std.CD4_RECENT_PCT_DATE_TEXT, std.SAMPLE_DT_NEG_TEXT, std.TTH_LAST_NEG_DATE_TEXT, std.RSD_STREET_ADDRESS1 || ' ' || RSD_STREET_ADDRESS2 RSD_STREET_ADDRESS, std.CUR_STREET_ADDRESS1 || ' ' || CUR_STREET_ADDRESS2 CUR_STREET_ADDRESS, std.SSN, std.STATENO, std.RIDR_STATENO, std.CITYNO, std.TRANS_CATEG, std.RSH_STATE_CD, std.RSA_STATE_CD, std.RSD_STATE_CD, std.RAD_STATE_CD, std.CUR_STATE_CD, std.STATE_CODE, std.SCORE, std.LAB_TEST_CD_HIV1, std.LAB_TEST_TYPE_HIV1, std.RESULT_HIV1, std.RESULT_INTERPRETATION_HIV1, std.RESULT_UNITS_HIV1, std.LAB_TEST_CD_HIV2, std.LAB_TEST_TYPE_HIV2, std.RESULT_HIV2, std.RESULT_INTERPRETATION_HIV2, std.RESULT_UNITS_HIV2, std.LAB_TEST_CD_HIV3, std.LAB_TEST_TYPE_HIV3, std.RESULT_HIV3, std.RESULT_INTERPRETATION_HIV3, std.RESULT_UNITS_HIV3, std.LAB_TEST_CD_AIDS, std.LAB_TEST_TYPE_AIDS, std.RESULT_AIDS, std.RESULT_UNITS_AIDS, std.OI_CD, std.VL_RECENT_VALUE, std.CD4_RECENT_CNT_VALUE, std.CD4_RECENT_PCT_VALUE, std.LAB_TEST_CD_NEG, std.LAB_TEST_TYPE_NEG, std.RESULT_NEG, std.RESULT_INTERPRETATION_NEG, std.RESULT_UNITS_NEG, std.COMMENTS, std.FIRST_NAME, std.MIDDLE_NAME, std.LAST_NAME, std.OPTIONAL1, std.OPTIONAL2, std.OPTIONAL3, std.OPTIONAL4, std.OPTIONAL5, std.OPTIONAL6, std.OPTIONAL7, std.OPTIONAL8, std.OPTIONAL9, std.OPTIONAL10, std.CURRENT_GENDER, std.HIV_CATEG, std.AIDS_CATEG, std.RSD_COUNTRY_CD, std.ETHNICITY, std.RSD_CITY_NAME, std.CUR_CITY_NAME, std.RSH_CITY_NAME, std.RSA_CITY_NAME, std.RSD_ZIP_CD, std.CUR_ZIP_CD, std.RSH_ZIP_CD, std.RSA_ZIP_CD, std.MATCH_SUMMARY, std.RSD_COUNTY_NAME, std.CUR_COUNTY_NAME, std.RSH_COUNTY_NAME, std.RSA_COUNTY_NAME
FROM STD_BLACK_BOX_DOC std LEFT OUTER JOIN person_doc_association pda ON (std.document_id = pda.document_id AND pda.dissassociation_date IS NULL) WHERE std.document_id = #{docId}
